export function registerAskUserTool(registry) { registry.register({ name: 'ask_user_question', description: '向用户提问并等待回答。仅在必要时使用：缺少无法通过工具或上下文推断的关键信息、存在多个候选需要用户定夺、执行破坏性操作前需要确认。优先 choice 类型（2-4 个选项，label 简短，description 补充说明）；开放性问题才用 text；一次只问真正必要的问题。', parameters: { type: 'object', properties: { questions: { type: 'array', description: '问题列表，通常只包含一个问题', items: { type: 'object', properties: { question: { type: 'string', description: '问题正文，具体明确，需要用户确认的路径等信息直接写进问题里' }, header: { type: 'string', description: '简短标签（不超过 8 个字），如"目录权限"' }, type: { type: 'string', enum: ['choice', 'text'], description: 'choice=选项选择，text=自由输入；省略时按是否提供 options 推断' }, options: { type: 'array', description: 'choice 类型的候选选项，2-4 个', items: { type: 'object', properties: { label: { type: 'string', description: '选项文案，简短明确' }, description: { type: 'string', description: '选项的补充说明' } }, required: ['label'] } }, multiSelect: { type: 'boolean', description: 'choice 是否可多选，默认单选' } }, required: ['question'] } } }, required: ['questions'] }, execute: async (args, ctx) => { ctx.signal?.throwIfAborted(); if (!ctx.askUser)
        throw new Error('user interaction is unavailable'); return JSON.stringify(await ctx.askUser((args.questions ?? []))); } }); }
